require "rails_helper"

RSpec.describe Timekeeping::Handoff::Checkpoint do
  def digest_case_entry(id, company_id)
    described_class::TABLES.fetch("entries").index_with { nil }.merge(
      "id" => id, "company_id" => company_id, "version" => 1, "project_id" => 10, "user_id" => 20,
      "work_date" => Date.new(2026, 1, 5), "duration" => 1.5, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "proof_metadata" => {}, "created_at" => Time.utc(2026, 1, 5, 10), "updated_at" => Time.utc(2026, 1, 5, 10)
    )
  end

  # "A checkpoint carries a row count and a checksum per table and per company, and every row carries company_id"
  it "carries a row count and a checksum for every table and every company" do
    tables = described_class::TABLES.keys.index_with { [] }
    tables["entries"] = [digest_case_entry(1, 7), digest_case_entry(2, 7), digest_case_entry(3, 8)]

    digest = described_class.build(tables:).digest

    expect(digest.fetch("entries").keys).to contain_exactly(7, 8)
    expect(digest.fetch("entries").fetch(7).fetch(:count)).to eq(2)
    expect(digest.fetch("entries").fetch(8).fetch(:count)).to eq(1)
    expect(digest.fetch("entries").fetch(7).fetch(:checksum)).to be_a(String).and(be_present)
    expect(digest.fetch("entries").fetch(7).fetch(:checksum)).not_to eq(digest.fetch("entries").fetch(8).fetch(:checksum))
  end
end

RSpec.describe Timekeeping::Handoff::Checkpoint do
  def last_bit_case_entry(id, company_id, duration)
    described_class::TABLES.fetch("entries").index_with { nil }.merge(
      "id" => id, "company_id" => company_id, "version" => 2, "project_id" => 10, "user_id" => 20,
      "work_date" => Date.new(2026, 1, 5), "duration" => duration, "note" => "n", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "proof_metadata" => {}, "created_at" => Time.utc(2026, 1, 5, 10), "updated_at" => Time.utc(2026, 1, 5, 10)
    )
  end

  def last_bit_case_digest(company_a_duration)
    tables = described_class::TABLES.keys.index_with { [] }
    tables["entries"] = [last_bit_case_entry(1, 1, company_a_duration), last_bit_case_entry(2, 2, 0.1 + 0.2)]
    tables["idempotency_records"] = [{
      "id" => 1, "company_id" => 1, "actor_type" => "User", "actor_id" => 20, "operation" => "create_entry",
      "key" => "k", "fingerprint" => "f", "status" => 201, "body" => "{}", "created_at" => Time.utc(2026, 1, 5)
    }.slice(*described_class::TABLES.fetch("idempotency_records"))]
    described_class.build(tables:).digest
  end

  # "The checksum must tell float values apart bit for bit."
  # "A changed field, or a float differing in its last bit, fails `verify` for that table and company only."
  it "changes only that table and company's checksum when a duration differs in its last bit" do
    duration = 0.1 + 0.2
    original = last_bit_case_digest(duration)
    changed = last_bit_case_digest(duration.next_float)

    expect(changed.dig("entries", 1, :checksum)).not_to eq(original.dig("entries", 1, :checksum))
    expect(changed.dig("entries", 1, :count)).to eq(original.dig("entries", 1, :count))
    expect(changed.dig("entries", 2)).to eq(original.dig("entries", 2))
    expect(changed.dig("idempotency_records", 1)).to eq(original.dig("idempotency_records", 1))
  end
end

RSpec.describe Timekeeping::Handoff::Checkpoint do
  def verify_case_checkpoint(company_a_note)
    entry = described_class::TABLES.fetch("entries").index_with { nil }.merge(
      "version" => 1, "project_id" => 10, "user_id" => 20, "work_date" => Date.new(2026, 1, 5), "duration" => 2.25,
      "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false, "source" => "manual",
      "source_metadata" => {}, "proof_metadata" => {}, "created_at" => Time.utc(2026, 1, 5, 10),
      "updated_at" => Time.utc(2026, 1, 5, 10)
    )
    tables = described_class::TABLES.keys.index_with { [] }
    tables["entries"] = [
      entry.merge("id" => 1, "company_id" => 1, "note" => company_a_note),
      entry.merge("id" => 2, "company_id" => 2, "note" => "b")
    ]
    described_class.build(tables:)
  end

  # "verify reports a mismatched row by table and company_id"
  it "verify reports a changed row by its table and company_id only" do
    original = JSON.parse(verify_case_checkpoint("a").to_json)
    changed = JSON.parse(verify_case_checkpoint("a changed").to_json)
    expect(described_class.verify(described_class.from_json(original.to_json))).to eq([])

    # The rows and the digest differ between the two transport forms. Taking one
    # of them from the changed checkpoint gives rows that no longer match the digest.
    differing_key = original.keys.find { |key| original[key] != changed[key] }
    tampered = original.merge(differing_key => changed[differing_key])

    mismatches = described_class.verify(described_class.from_json(tampered.to_json))

    expect(mismatches.map { |mismatch| [mismatch[:table], mismatch[:company_id]] }).to eq([["entries", 1]])
  end
end

RSpec.describe Timekeeping::Handoff::Checkpoint do
  # "A value that still has no home is refused as a backstop, naming the table; it is never dropped."
  it "refuses a row carrying a value with no canonical column, naming the table" do
    audit = {
      "id" => 1, "company_id" => 1, "entry_id" => 5, "actor_type" => "User", "actor_id" => 20, "action" => "update",
      "before" => { "note" => "" }, "after" => { "note" => "x" }, "entry_created_at" => Time.utc(2026, 1, 5),
      "created_at" => Time.utc(2026, 1, 5)
    }.slice(*described_class::TABLES.fetch("entry_audits"))
    tables = described_class::TABLES.keys.index_with { [] }
    tables["entry_audits"] = [audit.merge("changed_fields" => { "note" => ["", "x"] })]

    expect { described_class.build(tables:) }.to raise_error(/entry_audits/)

    tables["entry_audits"] = [audit.merge("company_id" => nil)]
    expect { described_class.build(tables:) }.to raise_error(/entry_audits/)
  end
end

RSpec.describe Timekeeping::Handoff::Checkpoint do
  # "Entry versions and duration floats survive export and load unchanged, bit for bit"
  it "keeps float bits and the digest through to_json and from_json" do
    entry = described_class::TABLES.fetch("entries").index_with { nil }.merge(
      "id" => 1, "company_id" => 1, "version" => 4, "project_id" => 10, "user_id" => 20,
      "work_date" => Date.new(2026, 1, 5), "duration" => (0.1 + 0.2).next_float, "note" => "",
      "bill_status" => "billed", "review_status" => "approved", "locked" => true, "source" => "manual",
      "source_metadata" => {}, "proof_metadata" => {}, "discarded_at" => Time.utc(2026, 2, 1, 0, 0, 0, 1),
      "created_at" => Time.utc(2026, 1, 5, 10, 0, 0, 123_456), "updated_at" => Time.utc(2026, 1, 6)
    )
    negative_zero = entry.merge("id" => 2, "duration" => -0.0)
    tables = described_class::TABLES.keys.index_with { [] }
    tables["entries"] = [entry, negative_zero]
    checkpoint = described_class.build(tables:)

    restored = described_class.from_json(checkpoint.to_json)

    expect(restored.digest).to eq(checkpoint.digest)
    expect(described_class.verify(restored)).to eq([])
    with_positive_zero = tables.merge("entries" => [entry, negative_zero.merge("duration" => 0.0)])
    expect(described_class.build(tables: with_positive_zero).digest).not_to eq(checkpoint.digest)
  end
end
